def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    highest_prev_bid = 0.0
    aggressive_count = 0
    desperate_opp = False
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev_bid:
                highest_prev_bid = bid
            if bid >= 90:
                aggressive_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_opp = True

    scarcity = supply < 2.0 * WATER_REQ
    abundance = supply >= 2.0 * WATER_REQ

    if hp <= 2 or no_water_days >= 2:
        if abundance:
            target = max(78.0, highest_prev_bid + 3.0)
        else:
            target = max(96.0, highest_prev_bid + 2.0)
        return float(min(budget, target))

    if hp <= 4 or no_water_days >= 1:
        if highest_prev_bid >= 110:
            if abundance:
                return float(min(budget, 76.0))
            return float(min(budget, 98.0))
        if highest_prev_bid >= 85:
            return float(min(budget, max(72.0, highest_prev_bid + 1.5)))
        return float(min(budget, 74.0 if abundance else 82.0))

    if scarcity:
        if aggressive_count >= 2 or highest_prev_bid >= 100:
            return float(min(budget, 8.0))
        if desperate_opp:
            return float(min(budget, 18.0))
        return float(min(budget, 24.0))

    if abundance:
        if highest_prev_bid >= 100:
            return float(min(budget, 58.0))
        if highest_prev_bid >= 80:
            return float(min(budget, 62.0))
        return float(min(budget, 54.0))

    if day >= 8 and hp >= 6:
        return float(min(budget, 30.0))

    return float(min(budget, 40.0))

