        return min(budget, DAILY_SALARY * 0.4)
    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    # Determine highest yesterday bid
    max_yesterday = max(yesterday_bids) if yesterday_bids else 0.0
    # Desperation threshold
    desperate = (hp <= 2) or (no_water_days > 0)
    # If desperate, go high (up to budget)
    if desperate:
        target = max(DAILY_SALARY * 0.9, min(budget, max_yesterday + 2.0))
        return min(budget, target)
    # Not desperate: be conservative but compete if yesterday was calm
    if max_yesterday < DAILY_SALARY * 0.5:
        # Low competition — bid moderately to win cheap
        return min(budget, max(DAILY_SALARY * 0.4, max_yesterday + 1.0))
    else:
        # High competition — avoid bidding war, stick to reasonable amount
        return min(budget, DAILY_SALARY * 0.55)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # If we can’t afford much, conserve.
    budget = float(my_status['budget'])
    hp = float(my_status['hp'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    # Read only yesterday's immediate behavior from previous_trace.
    prev_bids = []
    for opp in alive_opps:
        tr = opp.get('previous_trace') or {}
        if isinstance(tr, dict):
            bid = tr.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    # If we have no signal, choose a baseline.
    if not prev_bids:
        baseline = DAILY_SALARY * 0.55
        if hp <= 2:
            baseline = DAILY_SALARY * 0.85
        return max(0.0, min(budget, baseline))

    highest_prev_bid = max(prev_bids)

    # Determine how aggressively to bid based on yesterday's max pressure.
    # Eric showed sustained high bids (~114). Alex died after heavy pressure; avoid overpaying.
    # Also, if highest_prev_bid is extremely high, we must match a portion to avoid losing allocation.
    if highest_prev_bid >= 110:
        target = DAILY_SALARY * 0.75
    elif highest_prev_bid >= 80:
        target = DAILY_SALARY * 0.60
    else:
        target = DAILY_SALARY * 0.50

    # Adjust for our HP: low HP -> bid more.
    if hp <= 1.5:
        target *= 1.15
    elif hp <= 3.0:
        target *= 1.05

    # Adjust for supply: when supply is tight near our requirement, bid slightly more.
    # supply in [15,25], WATER_REQ=13 => tightness increases as supply approaches 15.
    tightness = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    # tightness ~1 when supply=15, ~0 when supply=25
    target *= (1.0 + 0.08 * tightness)

    # Cap bid to budget and avoid wasting too much salary.
    # Keep a floor to avoid being outbid when others are active.
    min_reasonable = DAILY_SALARY * 0.35
    bid = max(min_reasonable if highest_prev_bid >= 60 else 0.0, target)
    bid = min(bid, budget)

    # Final safety clamp.
    if bid < 0.0:
        bid = 0.0
    return float(bid)

